  const midpoint=(a,b)=>({x:(a.x+b.x)/2,y:(a.y+b.y)/2});
  function flatEnough(a,b,c,d,tolerance) {
    const dx=d.x-a.x,dy=d.y-a.y,len=dx*dx+dy*dy;
    const distance=p=>{
      if(len<1e-20)return Math.hypot(p.x-a.x,p.y-a.y);
      const u=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/len));
      return Math.hypot(p.x-a.x-u*dx,p.y-a.y-u*dy);
    };
    const poly=Math.hypot(a.x-b.x,a.y-b.y)+Math.hypot(b.x-c.x,b.y-c.y)+Math.hypot(c.x-d.x,c.y-d.y);
    return Math.max(distance(b),distance(c))<=tolerance && poly-Math.hypot(d.x-a.x,d.y-a.y)<=tolerance;
  }
  function flatten(a,b,c,d,out,tolerance,depth=0) {
    if(flatEnough(a,b,c,d,tolerance)){out.push(d);return;}
    if(depth>=20 || out.length>20000)throw new Error('字形曲線過於複雜，請縮小字高。');
    const ab=midpoint(a,b),bc=midpoint(b,c),cd=midpoint(c,d),abc=midpoint(ab,bc),bcd=midpoint(bc,cd),m=midpoint(abc,bcd);
    flatten(a,ab,abc,m,out,tolerance,depth+1);flatten(m,bcd,cd,d,out,tolerance,depth+1);
  }
