    const paths=[];let stroke=null,current=null;
    const tokens=(glyph.d||'').match(/[MLC]|[-+]?(?:\d*\.\d+|\d+\.?\d*)(?:[eE][-+]?\d+)?/g)||[];
    let i=0;const get=()=>{const v=Number(tokens[i++]);if(!Number.isFinite(v))throw new Error('單線字型座標無效。');return v/700;};
